final class OptionPopupControl: NSView, OptionControl {
    private let fixedWidth: CGFloat
    private let items: [String]
    private let read: () -> Int
    private let write: (Int) -> Void
    private let enabled: () -> Bool
    private let onEdit: () -> Void
    private var isActive = true
    private var hovered = false

    init(
        width: CGFloat, items: [String], read: @escaping () -> Int,
        write: @escaping (Int) -> Void, enabled: @escaping () -> Bool,
        onEdit: @escaping () -> Void
    ) {
        self.fixedWidth = width
        self.items = items
        self.read = read
        self.write = write
        self.enabled = enabled
        self.onEdit = onEdit
        super.init(frame: .zero)
        wantsLayer = true
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("OptionPopupControl does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: fixedWidth, height: DS.controlHeight)
    }

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        needsDisplay = true
    }

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Owner-filtered: a blanket removal takes `NSToolTipManager`'s area
        // with it and no tooltip on this control ever appears again — the
        // pitfall is written out in `Controls.swift`'s
        // `StickerButton.updateTrackingAreas`.
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: bounds, options: [.mouseEnteredAndExited, .activeInKeyWindow],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) {
        hovered = true
        needsDisplay = true
    }

    override func mouseExited(with event: NSEvent) {
        hovered = false
        needsDisplay = true
    }

    override func mouseDown(with event: NSEvent) {
        guard isActive else { return }
        let menu = NSMenu()
        let current = read()
        for (index, title) in items.enumerated() {
            let item = NSMenuItem(title: title, action: #selector(itemPicked(_:)), keyEquivalent: "")
            item.target = self
            item.tag = index
            item.state = index == current ? .on : .off
            menu.addItem(item)
        }
        menu.minimumWidth = bounds.width
        menu.popUp(positioning: nil, at: NSPoint(x: 0, y: bounds.height + 2), in: self)
    }
