import AppKit

// Does a right-click on a plain NSView with only a mouseDown override, or on an
// NSTextField, reach an enclosing view's menu(for:)? Records calls; answers nil so
// no menu tracks.
var calls: [String] = []

final class Row: NSStackView {
    override func menu(for event: NSEvent) -> NSMenu? {
        calls.append("row.menu(for:)")
        return nil
    }
}

final class PopupLike: NSView {
    override var intrinsicContentSize: NSSize { NSSize(width: 100, height: 22) }
    override func mouseDown(with event: NSEvent) { calls.append("popup.mouseDown") }
}

final class Field: NSTextField {
    override func menu(for event: NSEvent) -> NSMenu? {
        let m = super.menu(for: event)
        calls.append("field.menu(for:) -> \(m == nil ? "nil" : "menu \(m!.items.map(\.title))")")
        return nil
    }
}

let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let window = NSWindow(
    contentRect: NSRect(x: 2000, y: 2000, width: 400, height: 100), styleMask: [.titled],
    backing: .buffered, defer: false)
let popup = PopupLike()
popup.wantsLayer = true
let field = Field(string: "12")
field.isBezeled = false
let row = Row(views: [popup, field])
row.frame = NSRect(x: 0, y: 0, width: 400, height: 100)
row.orientation = .horizontal
window.contentView?.addSubview(row)
window.orderFront(nil)
window.contentView?.layoutSubtreeIfNeeded()

func rightClick(_ view: NSView, _ name: String) {
    calls = []
    let point = view.convert(NSPoint(x: view.bounds.midX, y: view.bounds.midY), to: nil)
    for type in [NSEvent.EventType.rightMouseDown, .rightMouseUp] {
        let event = NSEvent.mouseEvent(
            with: type, location: point, modifierFlags: [], timestamp: 0,
            windowNumber: window.windowNumber, context: nil, eventNumber: 0, clickCount: 1,
            pressure: 1)!
        window.sendEvent(event)
    }
    print(name, "hit:", String(describing: window.contentView?.hitTest(point).map { type(of: $0) }),
        calls)
}

rightClick(popup, "popup")
rightClick(field, "field at rest")
exit(0)

